package android.os;import java.util.*;public class Handler{public interface Callback{boolean handleMessage(Message m);}private final Callback c;private static class Task{Handler h;Runnable r;Task(Handler h,Runnable r){this.h=h;this.r=r;}}private static final ArrayDeque<Task> q=new ArrayDeque<>();public Handler(Looper l){c=null;}public Handler(Looper l,Callback c){this.c=c;}public boolean post(Runnable r){synchronized(q){q.add(new Task(this,r));}return true;}public void dispatch(Message m){post(()->c.handleMessage(m));}public void removeCallbacksAndMessages(Object o){synchronized(q){q.removeIf(t->t.h==this);}}public static void drain(){for(int i=0;i<1000;i++){Task t;synchronized(q){t=q.poll();}if(t==null)return;t.r.run();}throw new AssertionError("handler loop");}}
